content:
{
    "criteria": [
        {
            "id": "C1",
            "section": "合同主体审查",
            "criterion": "核实签约主体合法性与信息一致性",
            "check_points": [
                "通过国家企业信用信息公示系统或司法大数据平台核查该主体是否存在未结重大涉诉、被执行、失信、破产重整等风险信息",
                "核对营业执照登记的经营范围，确认合同标的（如软件采购）属于其核准经营范围内",
                "逐项比对合同首部载明的主体信息（名称、统一社会信用代码、注册地址、联系地址、联系电话、传真、法定代表人/负责人姓名及职务、指定联系人及联系方式）与最新工商登记信息是否完全一致",
                "如合同涉及软件等技术产品采购，核查卖方是否拥有该产品核心知识产权（如著作权登记证书、专利证书、授权链文件），或已获得合法有效的再许可权利"
            ]
        },
        {
            "id": "C2",
            "section": "合同框架完整性审查",
            "criterion": "确保合同必备条款齐全且结构完整",
            "check_points": [
                "检查合同是否完整包含以下核心条款：采购内容、合同金额、付款计划、合同期限、生效条件、知识产权归属与使用限制、产品质量/服务标准与保证、交付方式与地点、验收标准与程序、完成时限（含里程碑）、违约责任、争议解决（司法管辖或仲裁）、不可抗力、廉洁承诺条款、合同变更机制、合同份数及效力说明、电子送达约定",
                "确认合同中是否明确指定主要项目负责人，并完整记载其姓名、身份证号码及联系电话",
                "核查采购内容描述是否具体明确：包括品种、规格、型号、等级、花色等要素；若内容复杂，是否通过附件（如技术规格书、配置清单）予以详述并注明‘附件为本合同组成部分’"
            ]
        },
        {
            "id": "C3",
            "section": "合同金额与付款条款审查",
            "criterion": "确保金额表述准确、计量单位清晰、付款安排合理合规",
            "check_points": [
                "核对合同总金额是否同时以大小写规范书写，且二者数值严格一致；明确币种（如人民币/USD）、计量单位（如‘套’‘项’‘人天’）、单价与总价对应关系无误",
                "检查付款计划是否设置清晰节点（如签约后、到货后、初验合格后、终验通过后、维保期满后），各节点付款比例之和等于100%；是否预留不低于5%—10%尾款于免费维保期届满且无质量争议后支付",
                "确认付款前提是否明确（如‘凭合规增值税专用发票支付’），并注明发票类型、税率、开票主体与收款主体一致性要求"
            ]
        },
        {
            "id": "C4",
            "section": "合同期限与时间表述审查",
            "criterion": "确保期限定义精确、起止明确、避免歧义",
            "check_points": [
                "核查合同期限是否以具体起止日期（YYYY-MM-DD）或明确计算方式（如‘自双方签字盖章之日起满12个月’）载明，禁止使用‘长期’‘永久’等模糊表述",
                "确认所有时间节点（如交付日、验收日、付款日、维保截止日）均明示采用‘自然日’或‘工作日’；若约定季度/月度周期，须明确计算逻辑（如‘自X年X月X日起至第3个自然月最后一日止’或‘至X年X月X日前一日’）"
            ]
        },
        {
            "id": "C5",
            "section": "文本形式与逻辑一致性审查",
            "criterion": "保障合同文本规范性、内部逻辑自洽及法律援引有效性",
            "check_points": [
                "通读全文，识别并修正错别字、标点误用、标题层级混乱（如‘第一条’下直接出现‘1.3’而缺失‘1.1’‘1.2’）、语句成分残缺或歧义表达",
                "逐条比对正文与附件中相同事项的约定（如验收标准、知识产权归属、违约金计算方式），确保表述完全一致，无冲突或遗漏",
                "排查并删除招标文件、谈判纪要、询价函等前置流程中使用的非合同正式用语（如‘投标单位’‘响应人’‘谈判小组’），统一替换为‘甲方’‘乙方’‘本合同’等法定称谓",
                "核对合同首部‘甲方/乙方’全称、签署页‘签订主体名称’、骑缝章处名称、附件落款名称是否完全一致，不得存在简称、曾用名、漏字、多字或括号不匹配情形",
                "核查所援引法律法规名称、条款序号是否准确有效（如《民法典》第五百零九条而非《合同法》），现行有效且未被废止或修订替代",
                "确认合同正文末尾是否规范标注‘以下为合同签署栏’或‘以下无正文’字样，且该行与签署栏之间无空白行或冗余内容"
            ]
        }
    ]
}
